tool_input.command:
cat > /tmp/test-order-agent.mjs << 'EOF'
import { answerOrderQuestion } from './src/order-agent.js';
import { scriptedModel } from './test/helpers/mock-model.js';

// Test 1: Model calls getOrderStatus and gets valid order
const model1 = scriptedModel([
  {
    toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'A100' } }],
    usage: [100, 10],
  },
  { text: 'Your order A100 is shipped and will arrive on 2026-10-09.', usage: [200, 15] },
]);

const result1 = await answerOrderQuestion(model1, 'What is my order status?', {
  customerId: 'C1',
});

console.log('Test 1 (valid order):');
console.log('  answer:', result1.answer);
console.log('  lookedUp:', result1.lookedUp);
console.log('  inputTokens:', result1.inputTokens);
console.log('  outputTokens:', result1.outputTokens);
console.log('');

// Test 2: Model calls tool but order belongs to different customer
const model2 = scriptedModel([
  {
    toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'B200' } }],
    usage: [100, 10],
  },
  { text: 'I cannot find that order.', usage: [200, 15] },
]);

const result2 = await answerOrderQuestion(model2, 'What is order B200?', {
  customerId: 'C1',
});

console.log('Test 2 (unauthorized order):');
console.log('  answer:', result2.answer);
console.log('  lookedUp:', result2.lookedUp);
console.log('  inputTokens:', result2.inputTokens);
console.log('  outputTokens:', result2.outputTokens);
console.log('');

// Test 3: Tool calls multiple times
const model3 = scriptedModel([
  {
    toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'A100' } }],
    usage: [100, 10],
  },
  {
    toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'A101' } }],
    usage: [150, 12],
  },
  { text: 'You have two orders: A100 is shipped, A101 is processing.', usage: [250, 20] },
]);

const result3 = await answerOrderQuestion(model3, 'Tell me about my orders', {
  customerId: 'C1',
});

console.log('Test 3 (multiple tool calls):');
console.log('  answer:', result3.answer);
console.log('  lookedUp:', result3.lookedUp);
console.log('  inputTokens:', result3.inputTokens);
console.log('  outputTokens:', result3.outputTokens);
EOF
node /tmp/test-order-agent.mjs
